"""Builds AtomForgeIcons.h: the interface icons as a small font compiled into
AtomForge, so every platform shows the same icons without system fonts.

The glyphs are a subset of the Codicons icon font by Microsoft
(https://github.com/microsoft/vscode-codicons, CC BY 4.0, see
LICENSE-Codicons.txt), renamed "AtomForge Icons". Run with fontTools
installed, giving a codicon.ttf (from the Codicons release, or the copy in a
Visual Studio Code installation under resources/app/out/media):

    python make_icon_font.py path/to/codicon.ttf

ICONS lists the interface name (the Icon namespace in src/ui/Fonts.h) and the
Codicon glyph name; the generated header holds both the font and the code
points, so Fonts.h never needs editing by hand.
"""
import io
import pathlib
import sys

from fontTools import subset
from fontTools.ttLib import TTFont

ICONS = [
    ("Open", "folder-opened"),
    ("Save", "save"),
    ("Undo", "discard"),
    ("Redo", "redo"),
    ("Home", "home"),
    ("Ruler", "arrow-both"),
    ("Rotate", "refresh"),
    ("Info", "info"),
    ("Warning", "warning"),
    ("Error", "error"),
    ("Check", "pass"),
    ("Add", "add"),
    ("Delete", "trash"),
    ("Settings", "settings-gear"),
    ("Build", "edit"),
    ("Cube", "package"),
    ("Help", "question"),
    ("Camera", "device-camera"),
    ("Folder", "folder"),
    ("Document", "symbol-file"),
    ("Play", "play"),
    ("Pipeline", "layers"),
    ("Search", "search"),
    ("Pause", "debug-pause"),
    ("Previous", "debug-reverse-continue"),
    ("Next", "debug-continue"),
]


def main(source):
    font = TTFont(source)
    by_name = {}
    for code, name in font.getBestCmap().items():
        by_name.setdefault(name, code)
    missing = [glyph for _, glyph in ICONS if glyph not in by_name]
    if missing:
        raise SystemExit(f"glyphs not in {source}: {missing}")
    codes = [(icon, glyph, by_name[glyph]) for icon, glyph in ICONS]
    options = subset.Options()
    options.name_IDs = [0, 1, 2, 3, 4, 5, 6]
    options.notdef_outline = True
    options.hinting = False
    options.drop_tables += ["FFTM"]
    subsetter = subset.Subsetter(options)
    subsetter.populate(unicodes=sorted({code for _, _, code in codes}))
    subsetter.subset(font)
    for record in font["name"].names:
        if record.nameID in (1, 4, 16):
            record.string = "AtomForge Icons"
        elif record.nameID == 6:
            record.string = "AtomForgeIcons"
    data = io.BytesIO()
    font.save(data)
    blob = data.getvalue()
    lines = ["// Generated by make_icon_font.py: the interface icons, a subset of the Codicons",
             "// font by Microsoft (CC BY 4.0, LICENSE-Codicons.txt) renamed \"AtomForge Icons\".",
             "#pragma once", "", "namespace atomforgeIcons", "{",
             "// Code points of the icons (Private Use Area), in the order of src/ui/Fonts.h.",
             "enum : unsigned int", "{"]
    for icon, glyph, code in codes:
        lines.append(f"    k{icon} = 0x{code:04X},  // {glyph}")
    lines += ["};", "",
              "// The glyph ranges of the font, for ImFontConfig (pairs, zero-terminated).",
              "inline constexpr unsigned short kRanges[] = {"
              + ", ".join(f"0x{c:04X}, 0x{c:04X}" for c in sorted({code for _, _, code in codes})) + ", 0};", "",
              f"inline constexpr unsigned int kFontSize = {len(blob)};",
              "alignas(4) inline const unsigned char kFontData[] = {"]
    for start in range(0, len(blob), 20):
        lines.append("    " + ", ".join(f"0x{b:02x}" for b in blob[start:start + 20]) + ",")
    lines += ["};", "}", ""]
    here = pathlib.Path(__file__).resolve().parent
    (here / "AtomForgeIcons.h").write_text("\n".join(lines), encoding="ascii")
    # The icons as UTF-8 strings, for labels (included by src/ui/Fonts.h).
    codes_header = ["// Generated by make_icon_font.py: the interface icons of AtomForgeIcons.h as",
                    "// UTF-8 strings (Codicons glyph names in the comments).",
                    "#pragma once", "", "namespace Icon", "{"]
    for icon, glyph, code in codes:
        escaped = "".join(f"\\x{b:02x}" for b in chr(code).encode("utf-8"))
        codes_header.append(f'inline constexpr const char* {icon} = "{escaped}";  // U+{code:04X} {glyph}')
    codes_header += ["}", ""]
    (here / "AtomForgeIconCodes.h").write_text("\n".join(codes_header), encoding="ascii")
    print(f"{len(codes)} icons, {len(blob)} bytes")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    main(sys.argv[1])
